function solution(timestamps, windowMs, maxRequests) {
  const accepted = [];
  const out = [];
  for (const t of timestamps || []) {
    while (accepted.length > 0 && accepted[0] <= t - windowMs) {
      accepted.shift();
    }
    if (accepted.length < maxRequests) {
      accepted.push(t);
      out.push(true);
    } else {
      out.push(false);
    }
  }
  return out;
}

