function solution(comments) {
  const map = new Map();
  const roots = [];
  for (const c of comments || []) {
    map.set(c.id, { id: c.id, text: c.text, children: [] });
  }
  for (const c of comments || []) {
    const node = map.get(c.id);
    if (c.parentId && map.has(c.parentId)) {
      map.get(c.parentId).children.push(node);
    } else {
      roots.push(node);
    }
  }
  return roots;
}

